public class DriverFactory {
    private static ThreadLocal<WebDriver> driver = new ThreadLocal<>();

    public static WebDriver getDriver() {
        if (driver.get() == null) {
            String browser = ConfigReader.getProperty("browser");
            switch (browser.toLowerCase()) {
                case "chrome":
                    WebDriverManager.chromedriver().setup();
                    ChromeOptions options = new ChromeOptions();
                    options.addArguments("--headless", "--disable-gpu");
                    driver.set(new ChromeDriver(options));
                    break;
                case "firefox":
                    WebDriverManager.firefoxdriver().setup();
                    driver.set(new FirefoxDriver());
                    break;
                default:
                    throw new RuntimeException("Unsupported browser: " + browser);
            }
            driver.get().manage().window().maximize();
            driver.get().manage().timeouts().implicitlyWait(
                Duration.ofSeconds(10));
        }
        return driver.get();
    }

    public static void quitDriver() {
        if (driver.get() != null) {
            driver.get().quit();
            driver.remove();
        }
    }
}

public class WaitUtils {
    private static final int DEFAULT_TIMEOUT = 30;

    public static WebElement waitForElementVisible(By locator) {
        return new WebDriverWait(DriverFactory.getDriver(), 
                Duration.ofSeconds(DEFAULT_TIMEOUT))
            .until(ExpectedConditions.visibilityOfElementLocated(locator));
    }

    public static boolean waitForElementToDisappear(By locator) {
        return new WebDriverWait(DriverFactory.getDriver(), 
                Duration.ofSeconds(DEFAULT_TIMEOUT))
            .until(ExpectedConditions.invisibilityOfElementLocated(locator));
    }

    public static WebElement waitForElementClickable(By locator) {
        return new WebDriverWait(DriverFactory.getDriver(), 
                Duration.ofSeconds(DEFAULT_TIMEOUT))
            .until(ExpectedConditions.elementToBeClickable(locator));
    }

    public static void waitForPageLoad() {
        new WebDriverWait(DriverFactory.getDriver(), 
                Duration.ofSeconds(DEFAULT_TIMEOUT))
            .until(driver -> 
                ((JavascriptExecutor) driver).executeScript(
                    "return document.readyState").equals("complete"));
    }
}

