public class KeywordDriver {
    private Map<String, KeywordFunction> keywordMap;

    public KeywordDriver() {
        keywordMap = new HashMap<>();
        initializeKeywords();
    }

    private void initializeKeywords() {
        // Register all available keywords
        keywordMap.put("OpenBrowser", (params) -> {
            String browser = params[0];
            DriverFactory.initializeDriver(browser);
        });

        keywordMap.put("NavigateTo", (params) -> {
            String url = params[0];
            DriverFactory.getDriver().get(url);
        });

        keywordMap.put("EnterText", (params) -> {
            String locator = params[0];
            String text = params[1];
            Driver.findElement(By.id(locator)).sendKeys(text);
        });

        keywordMap.put("Click", (params) -> {
            String locator = params[0];
            Driver.findElement(By.id(locator)).click();
        });
    }

    public void executeTest(List<TestStep> testSteps) {
        for (TestStep step : testSteps) {
            try {
                KeywordFunction function = keywordMap.get(step.getKeyword());
                if (function != null) {
                    function.execute(step.getParameters());
                } else {
                    throw new RuntimeException("Unknown keyword: " + step.getKeyword());
                }
            } catch (Exception e) {
                // Log error and continue or stop based on configuration
                System.out.println("Error executing step: " + step);
                throw e;
            }
        }
    }
}

// Functional interface for keyword implementation
