public class ExcelUtils {

    private static Workbook workbook;
    private static Sheet sheet;
    private static String filePath;

    // Initialize Excel file
    public static void initializeExcel(String path, String sheetName) {
        try {
            filePath = path;
            FileInputStream fis = new FileInputStream(new File(filePath));

            // Determine file type and create appropriate workbook
            if (path.endsWith(".xlsx")) {
                workbook = new XSSFWorkbook(fis);
            } else if (path.endsWith(".xls")) {
                workbook = new HSSFWorkbook(fis);
            } else {
                throw new IllegalArgumentException("Unsupported file format");
            }

            sheet = workbook.getSheet(sheetName);
            fis.close();

        } catch (IOException e) {
            throw new RuntimeException("Failed to initialize Excel file: " + e.getMessage());
        }
    }

    // Get cell value as string
    public static String getCellData(int rowNum, int colNum) {
        try {
            Row row = sheet.getRow(rowNum);
            if (row == null) return "";

            Cell cell = row.getCell(colNum);
            if (cell == null) return "";

            // Handle different cell types
            switch (cell.getCellType()) {
                case STRING:
                    return cell.getStringCellValue();
                case NUMERIC:
                    if (DateUtil.isCellDateFormatted(cell)) {
                        return cell.getDateCellValue().toString();
                    } else {
                        return String.valueOf(cell.getNumericCellValue());
                    }
                case BOOLEAN:
                    return String.valueOf(cell.getBooleanCellValue());
                case FORMULA:
                    return cell.getCellFormula();
                default:
                    return "";
            }
        } catch (Exception e) {
            return "";
        }
    }

    // Get cell value with column name
    public static String getCellData(int rowNum, String colName) {
        int colNum = getColumnNumber(colName);
        return getCellData(rowNum, colNum);
    }

    // Set cell value
    public static void setCellData(int rowNum, int colNum, String value) {
        try {
            Row row = sheet.getRow(rowNum);
            if (row == null) {
                row = sheet.createRow(rowNum);
            }

            Cell cell = row.getCell(colNum);
            if (cell == null) {
                cell = row.createCell(colNum);
            }

            cell.setCellValue(value);

            // Write changes to file
            FileOutputStream fos = new FileOutputStream(filePath);
            workbook.write(fos);
            fos.close();

        } catch (IOException e) {
            throw new RuntimeException("Failed to set cell data: " + e.getMessage());
        }
    }

    // Get total rows count
    public static int getRowCount() {
        return sheet.getPhysicalNumberOfRows();
    }

    // Get total columns count
    public static int getColumnCount() {
        Row row = sheet.getRow(0);
        return row.getPhysicalNumberOfCells();
    }

    // Get column number by name
    public static int getColumnNumber(String colName) {
        Row headerRow = sheet.getRow(0);
        for (int i = 0; i < headerRow.getPhysicalNumberOfCells(); i++) {
            if (headerRow.getCell(i).getStringCellValue().equalsIgnoreCase(colName)) {
                return i;
            }
        }
        throw new RuntimeException("Column not found: " + colName);
    }

    // Get all data as 2D array
    public static Object[][] getTestData(String sheetName) {
        initializeExcel(filePath, sheetName);

        int rowCount = getRowCount();
        int colCount = getColumnCount();

        Object[][] data = new Object[rowCount - 1][colCount];

        for (int i = 1; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                data[i - 1][j] = getCellData(i, j);
            }
        }

        return data;
    }

    // Close workbook
    public static void closeWorkbook() {
        try {
            if (workbook != null) {
                workbook.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

