public static List<Map<String, String>> getTestDataAsMap(String sheetName) {
    initializeExcel(filePath, sheetName);

    List<Map<String, String>> testData = new ArrayList<>();
    Row headerRow = sheet.getRow(0);

    for (int i = 1; i < getRowCount(); i++) {
        Map<String, String> rowData = new HashMap<>();
        Row row = sheet.getRow(i);

        for (int j = 0; j < getColumnCount(); j++) {
            String key = headerRow.getCell(j).getStringCellValue();
            String value = getCellData(i, j);
            rowData.put(key, value);
        }
        testData.add(rowData);
    }
    return testData;
}

public static Object[][] getRunModeTestCases(String sheetName) {
    List<Map<String, String>> allData = getTestDataAsMap(sheetName);
    List<Map<String, String>> filteredData = new ArrayList<>();

    for (Map<String, String> row : allData) {
        if ("Y".equalsIgnoreCase(row.get("RunMode"))) {
            filteredData.add(row);
        }
    }

    // Convert to 2D array for TestNG DataProvider
    Object[][] data = new Object[filteredData.size()][1];
    for (int i = 0; i < filteredData.size(); i++) {
        data[i][0] = filteredData.get(i);
    }
    return data;
}

public static void writeTestResult(String testCaseId, String status, String errorMsg) {
    try {
        Sheet resultSheet = workbook.getSheet("Results");
        int lastRow = resultSheet.getLastRowNum() + 1;

        Row row = resultSheet.createRow(lastRow);
        row.createCell(0).setCellValue(testCaseId);
        row.createCell(1).setCellValue(new Date().toString());
        row.createCell(2).setCellValue(status);
        row.createCell(3).setCellValue(errorMsg);

        FileOutputStream fos = new FileOutputStream(filePath);
        workbook.write(fos);
        fos.close();

    } catch (IOException e) {
        e.printStackTrace();
    }
}

