public class BaseTest {

    protected WebDriver driver;
    protected Properties config;

    @BeforeSuite
    public void beforeSuite() {
        // Load configuration
        config = ConfigReader.loadProperties("config.properties");

        // Initialize Excel utilities
        ExcelUtils.initializeExcel(
            config.getProperty("testdata.path"), 
            "LoginTestCases"
        );
    }

    @BeforeMethod
    public void setUp(ITestContext context) {
        // Browser setup based on configuration
        String browser = config.getProperty("browser", "chrome");
        driver = WebDriverFactory.createDriver(browser);
        driver.manage().window().maximize();
        driver.manage().timeouts().implicitlyWait(
            Duration.ofSeconds(Long.parseLong(config.getProperty("timeout")))
        );

        // Set driver in context for listeners
        context.setAttribute("driver", driver);
    }

    @AfterMethod
    public void tearDown(ITestResult result) {
        // Capture screenshot on failure
        if (result.getStatus() == ITestResult.FAILURE) {
            TestUtils.captureScreenshot(driver, result.getName());
        }

        // Close browser
        if (driver != null) {
            driver.quit();
        }
    }

    @AfterSuite
    public void afterSuite() {
        ExcelUtils.closeWorkbook();
    }
}

