public class DataProviderClass {

    @DataProvider(name = "loginData")
    public static Object[][] getLoginTestData() {
        return ExcelUtils.getRunModeTestCases("LoginTestData");
    }

    @DataProvider(name = "loginDataAsMap")
    public static Object[][] getLoginTestDataAsMap() {
        List<Map<String, String>> testData = ExcelUtils.getTestDataAsMap("LoginTestData");

        // Filter by RunMode from TestCases sheet
        List<Map<String, String>> filteredData = new ArrayList<>();
        for (Map<String, String> data : testData) {
            String testCaseId = data.get("TestCaseID");
            if (isTestCaseEnabled(testCaseId)) {
                filteredData.add(data);
            }
        }

        Object[][] dataArray = new Object[filteredData.size()][1];
        for (int i = 0; i < filteredData.size(); i++) {
            dataArray[i][0] = filteredData.get(i);
        }
        return dataArray;
    }

    private static boolean isTestCaseEnabled(String testCaseId) {
        ExcelUtils.initializeExcel(ConfigReader.getProperty("testdata.path"), "LoginTestCases");
        int rowCount = ExcelUtils.getRowCount();

        for (int i = 1; i < rowCount; i++) {
            String currentTestCaseId = ExcelUtils.getCellData(i, "TestCaseID");
            if (testCaseId.equals(currentTestCaseId)) {
                String runMode = ExcelUtils.getCellData(i, "RunMode");
                return "Y".equalsIgnoreCase(runMode);
            }
        }
        return false;
    }
}

