public class LoginTests extends BaseTest {

    private LoginPage loginPage;
    private DashboardPage dashboardPage;

    @BeforeMethod
    public void pageSetup() {
        loginPage = new LoginPage(driver);
        dashboardPage = new DashboardPage(driver);
        driver.get(ConfigReader.getProperty("app.url"));
    }

    @Test(dataProvider = "loginDataAsMap", dataProviderClass = DataProviderClass.class)
    public void testLoginFunctionality(Map<String, String> testData) {
        String testCaseId = testData.get("TestCaseID");
        String dataId = testData.get("DataID");
        String username = testData.get("Username");
        String password = testData.get("Password");
        String expectedResult = testData.get("ExpectedResult");

        // Perform login
        loginPage.enterUsername(username);
        loginPage.enterPassword(password);
        loginPage.clickLoginButton();

        // Verify result based on expected outcome
        switch (expectedResult) {
            case "SUCCESS":
                Assert.assertTrue(dashboardPage.isDashboardDisplayed(), 
                    "Dashboard should be displayed after successful login");
                break;

            case "INVALID_CREDENTIALS":
                String actualError = loginPage.getErrorMessage();
                Assert.assertTrue(actualError.contains("Invalid"), 
                    "Should show invalid credentials error");
                break;

            case "EMPTY_CREDENTIALS":
                Assert.assertTrue(loginPage.isLoginPageDisplayed(), 
                    "Should remain on login page for empty credentials");
                break;

            default:
                Assert.fail("Unknown expected result: " + expectedResult);
        }

        // Write result to Excel
        ExcelUtils.writeTestResult(testCaseId + "_" + dataId, "PASS", "");
    }

    @Test
    public void testLoginPageElements() {
        Assert.assertTrue(loginPage.isUsernameFieldDisplayed(), "Username field should be displayed");
        Assert.assertTrue(loginPage.isPasswordFieldDisplayed(), "Password field should be displayed");
        Assert.assertTrue(loginPage.isLoginButtonDisplayed(), "Login button should be displayed");
    }
}

