public class BaseIntegratedTest {

    protected WebDriver driver;
    protected RequestSpecification apiRequest;
    protected Connection dbConnection;
    protected TestDataFactory testData;
    protected static ExtentReports extent;
    protected ExtentTest test;

    @BeforeSuite
    public void beforeSuite() {
        // Initialize reporting
        extent = ReportUtils.initExtentReport();

        // Initialize database connection
        dbConnection = DbUtils.getConnection();

        // Initialize test data factory
        testData = new TestDataFactory();
    }

    @BeforeMethod
    public void setUp(Method method) {
        // Create test in report
        test = extent.createTest(method.getName());

        // Initialize API client
        apiRequest = ApiUtils.getDefaultRequest()
            .filter(new RequestLoggingFilter())
            .filter(new ResponseLoggingFilter());

        // Initialize WebDriver
        driver = WebDriverUtils.createDriver();
        driver.manage().window().maximize();

        // Setup test context
        TestContext.setDriver(driver);
        TestContext.setApiRequest(apiRequest);
        TestContext.setDbConnection(dbConnection);
        TestContext.setExtentTest(test);
    }

    @AfterMethod
    public void tearDown(ITestResult result) {
        // Log test result
        if (result.getStatus() == ITestResult.FAILURE) {
            test.fail("Test failed: " + result.getThrowable());
            // Capture screenshot for UI tests
            if (driver != null) {
                String screenshotPath = WebDriverUtils.captureScreenshot(driver, result.getName());
                test.addScreenCaptureFromPath(screenshotPath);
            }
        } else if (result.getStatus() == ITestResult.SUCCESS) {
            test.pass("Test passed");
        }

        // Cleanup test data
        cleanupTestData();

        // Close WebDriver
        if (driver != null) {
            driver.quit();
        }
    }

    @AfterSuite
    public void afterSuite() throws SQLException {
        // Close database connection
        if (dbConnection != null && !dbConnection.isClosed()) {
            dbConnection.close();
        }

        // Flush extent reports
        if (extent != null) {
            extent.flush();
        }
    }

    protected void cleanupTestData() {
        // Implementation for cleaning up test data created during test
        try {
            DbUtils.cleanupTestData(dbConnection, testData.getTestRunId());
        } catch (SQLException e) {
            test.warning("Failed to cleanup test data: " + e.getMessage());
        }
    }
}

