    def test_sql_injection(self, endpoint, method='GET', params=None):
        """Test for SQL injection vulnerabilities"""
        sql_payloads = ["' OR '1'='1", "'; DROP TABLE users--", "1' UNION SELECT 1,2,3--"]

        for payload in sql_payloads:
            test_params = params.copy() if params else {}
            for key in test_params:
                test_params[key] = payload

                if method.upper() == 'GET':
                    response = self.session.get(f"{self.base_url}{endpoint}", params=test_params)
                else:
                    response = self.session.post(f"{self.base_url}{endpoint}", json=test_params)

                if self._is_sql_injection_indication(response):
                    print(f"Potential SQL injection found in {key}: {payload}")

    def test_idor(self, endpoint_pattern, user_ids):
        """Test for Insecure Direct Object Reference"""
        for user_id in user_ids:
            endpoint = endpoint_pattern.format(user_id=user_id)
            response = self.session.get(f"{self.base_url}{endpoint}")

            if response.status_code == 200:
                print(f"IDOR vulnerability: Access to {endpoint}")

    def _is_sql_injection_indication(self, response):
        """Check response for SQL injection indicators"""
        indicators = ["sql", "mysql", "syntax", "database"]
        response_text = response.text.lower()
        return any(indicator in response_text for indicator in indicators)

