    tester = JWTSecurityTester(
        target_url="https://api.example.com",
        token="your_jwt_token_here"
    )

    tester.test_algorithm_confusion("public_key.pem")
    tester.test_none_algorithm()
    tester.test_weak_secrets("common_secrets.txt")

    tester.generate_report()

