pipeline {
    agent any

    stages {
        stage('JWT Security Scan') {
            steps {
                script {
                    // Run automated JWT security tests
                    sh 'python3 jwt_security_tester.py --target $API_URL --token $TEST_TOKEN'

                    // Run jwt_tool comprehensive scan
                    sh 'python3 jwt_tool.py $TEST_TOKEN -T -X a -X n -C -d common_secrets.txt'

                    // Generate security report
                    sh 'python3 generate_jwt_report.py --output reports/jwt-security.html'
                }
            }
            post {
                always {
                    // Archive security reports
                    archiveArtifacts artifacts: 'reports/**/*', allowEmptyArchive: true

                    // Publish HTML report
                    publishHTML([
                        allowMissing: true,
                        alwaysLinkToLastBuild: true,
                        keepAll: true,
                        reportDir: 'reports',
                        reportFiles: 'jwt-security.html',
                        reportName: 'JWT Security Report'
                    ])
                }
                failure {
                    // Notify on critical vulnerabilities
                    emailext (
                        subject: "CRITICAL: JWT Security Vulnerabilities Found",
                        body: "Critical JWT security vulnerabilities detected in build ${env.BUILD_NUMBER}",
                        to: "security-team@company.com"
                    )
                }
            }
        }
    }
}
